<script setup>
import { onMounted, reactive, ref } from 'vue'
import api from '../services/api'
const business = ref(null); const branches = ref([]); const showForm = ref(false); const error = ref(''); const form = reactive({ name: '', code: '', mobile: '', address: '' })
const messageFor = error => error.response?.data?.errors?.code?.[0] || error.response?.data?.message || 'শাখা সংরক্ষণ করা যায়নি।'
const load = async () => { const { data } = await api.get('/businesses'); business.value = data.data[0]; if (business.value) { const response = await api.get(`/businesses/${business.value.id}/branches`); branches.value = response.data.data } }
onMounted(load)
const add = async () => { error.value = ''; try { await api.post(`/businesses/${business.value.id}/branches`, form); Object.assign(form, { name: '', code: '', mobile: '', address: '' }); showForm.value = false; load() } catch (e) { error.value = messageFor(e) } }
const edit = async branch => { const name = prompt('শাখার নাম', branch.name); if (!name) return; error.value = ''; try { await api.put(`/branches/${branch.id}`, { name }); load() } catch (e) { error.value = messageFor(e) } }
</script>
<template><section><div class="page-heading inline"><div><p class="eyebrow">BUSINESS NETWORK</p><h2>শাখাসমূহ</h2><p>প্রতিষ্ঠানের শাখা ও অবস্থান পরিচালনা করুন।</p></div><button class="primary" @click="showForm=true">+ নতুন শাখা</button></div><p v-if="error" class="error">{{ error }}</p><div v-if="showForm" class="page-card compact"><form class="form-grid" @submit.prevent="add"><label>শাখার নাম<input v-model="form.name" required /></label><label>শাখা কোড<input v-model="form.code" required /><small>এই ব্যবসার প্রতিটি শাখার কোড আলাদা হতে হবে।</small></label><label>মোবাইল<input v-model="form.mobile" /></label><label>ঠিকানা<input v-model="form.address" /></label><div class="form-actions full-width"><button type="button" class="secondary" @click="showForm=false">বাতিল</button><button class="primary">শাখা সংরক্ষণ করুন</button></div></form></div><div class="table-card"><table><thead><tr><th>শাখা</th><th>কোড</th><th>মোবাইল</th><th>অবস্থা</th><th></th></tr></thead><tbody><tr v-for="branch in branches" :key="branch.id"><td><strong>{{ branch.name }}</strong><small>{{ branch.address || 'ঠিকানা দেওয়া হয়নি' }}</small></td><td>{{ branch.code || '—' }}</td><td>{{ branch.mobile || '—' }}</td><td><span class="status active">● সক্রিয়</span></td><td><button class="secondary small" @click="edit(branch)">সম্পাদনা</button></td></tr><tr v-if="!branches.length"><td colspan="5" class="empty">কোনো শাখা পাওয়া যায়নি।</td></tr></tbody></table></div></section></template>
